@Label1:
	If ($Talkzixuan17 == 0) @Talk0;
	If ($Talkzixuan17 == 1) @Talk1;	
	Goto @end;
@Talk0:
	If ($ZiXuanSense >> 20) @AddSenseEnd;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd:
	Say("紫轩：每次经过这里，都令人感到神清气爽，杨公子，你觉得呢？",	16);
	Say("杨影枫：有佳人相伴，即使地狱亦为仙界呀。",	3);
	Say("紫轩（含羞低头，面飞红云）：……", 122);
	Assign($Talkzixuan17, 1);
	Goto @end;
@Talk1:
	If ($ZiXuanSense >> 20) @AddSenseEnd1;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd1:
	Talk(2072, 2073);
	Goto @end;	


@Label3:
	If ($ZiXuanSense >> 20) @AddSenseEnd2;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd2:
	Say("紫轩：杨公子，你的梦想就是成为武功天下第一吗？", 16);
	Say("样影枫：是啊，这是我的理想，紫轩，你呢？你的梦想是什么？", 3);
	Say("紫轩：我希望能够找到一个樱花谷那样的清净之地，过一种与世无争、远离烦忧的生活。", 16);
	Return;

@Label2:	
	If ($Talkzixuan172 == 0) @Talk2;
	If ($Talkzixuan172 == 1) @Talk3;	
	Goto @end;
@Talk2:
	If ($ZiXuanSense >> 20) @AddSenseEnd3;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd3:
	Talk(2384, 2385);
	Assign($Talkzixuan172, 1);
	Goto @end;
@Talk3:
	If ($ZiXuanSense >> 20) @AddSenseEnd4;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd4:
	Say("紫轩：这里的泉水真清啊。", 16);
	Say("杨影枫：泉水再清，也比不上你的眼睛清澈。", 3);
	Say("紫轩（面飞红云）：……", 122);
	Goto @end;


@end:
	Return;

